package com.reporting.service;

import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import javax.servlet.http.HttpServletRequest;
import java.util.*;
import java.io.*;
import java.nio.file.*;

@RestController
@RequestMapping("/api/export")
public class ReportExportController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private static final String TEMPLATE_DIR = "/opt/app/templates/";
    private static final List<String> ALLOWED_FORMATS = Arrays.asList("csv", "xlsx", "pdf");

    @PostMapping("/generate")
    public Map<String, Object> generateExport(
            @RequestParam String reportId,
            @RequestParam String format,
            @RequestParam(required = false) String templateName,
            HttpServletRequest request) {

        Map<String, Object> response = new HashMap<>();

        // Validate format
        if (!ALLOWED_FORMATS.contains(format.toLowerCase())) {
            response.put("error", "Invalid format");
            return response;
        }

        // Fetch report metadata
        String query = "SELECT report_name, owner, created_at FROM reports WHERE id = ?";
        Map<String, Object> reportMeta = jdbcTemplate.queryForMap(query, reportId);

        // Template resolution - user can specify custom template
        String templatePath;
        if (templateName != null && !templateName.isEmpty()) {
            // Normalize the path to prevent obvious traversal
            templatePath = TEMPLATE_DIR + templateName.replace("\\", "/");
        } else {
            templatePath = TEMPLATE_DIR + "default_" + format + ".tpl";
        }

        // Read template file
        String templateContent;
        try {
            templateContent = new String(Files.readAllBytes(Paths.get(templatePath)));
        } catch (IOException e) {
            response.put("error", "Template not found: " + templateName);
            return response;
        }

        // Process template with report data
        String processed = processTemplate(templateContent, reportMeta);

        // Write output
        String outputFile = "/tmp/exports/" + reportId + "_" + System.currentTimeMillis() + "." + format;
        try {
            Files.write(Paths.get(outputFile), processed.getBytes());
        } catch (IOException e) {
            response.put("error", "Failed to write export");
            return response;
        }

        response.put("status", "success");
        response.put("downloadPath", "/downloads/" + Paths.get(outputFile).getFileName());
        response.put("reportName", reportMeta.get("report_name"));
        return response;
    }

    @GetMapping("/templates")
    public List<String> listTemplates(@RequestParam(required = false) String subdir) {
        String dir = TEMPLATE_DIR;
        if (subdir != null) {
            dir = TEMPLATE_DIR + subdir + "/";
        }
        File folder = new File(dir);
        String[] files = folder.list();
        return files != null ? Arrays.asList(files) : Collections.emptyList();
    }

    private String processTemplate(String template, Map<String, Object> data) {
        String result = template;
        for (Map.Entry<String, Object> entry : data.entrySet()) {
            result = result.replace("{{" + entry.getKey() + "}}", 
                    entry.getValue() != null ? entry.getValue().toString() : "");
        }
        return result;
    }
}
